    let output = '\n╔══════════════════════════════════════╗\n';
    output += '║       ओशो जीवन समयरेखा              ║\n';
    output += '╚══════════════════════════════════════╝\n';

    for (const period of this.periods) {
      output += `\n📅 ${period.name} (${period.years})\n`;
      output += `   ${period.significance}\n`;
      for (const event of period.keyEvents) {
